{
  "summary": "El kansetsu-waza solo se puede aplicar a la articulación del codo, estando prohibido en cualquier otra articulación [SOR-2026-08-P191-S198].",
  "normative_basis": "La base normativa se encuentra en el artículo 18.2.2 de las Reglas Deportivas y de Organización de la IJF (Pág. 191), el cual establece las infracciones graves de hansoku-make por actos contra el espíritu del judo, prohibiendo específicamente la aplicación de kansetsu-waza en cualquier articulación distinta al codo [SOR-2026-08-P191-S198].",
  "citations": [
    "SOR-2026-08-P191-S198"
  ],
  "conditions_and_exceptions": "Se prohíbe aplicar kansetsu-waza a cualquier articulación que no sea el codo, considerándose una infracción penalizada con hansoku-make directo [SOR-2026-08-P191-S198].",
  "extended_analysis": "No aplica.",
  "limitations": "Ninguna.",
  "answerability": "RESPALDADA",
  "evidence_quotes": [
    {
      "passage_id": "SOR-2026-08-P191-S198",
      "quote": "To apply kansetsu-waza to any joint other than the elbow joint (e.g., ashi-garami)",
      "supports": "Prohibición de aplicar kansetsu-waza a articulaciones distintas al codo"
    },
    {
      "passage_id": "SOR-2026-08-P191-S198",
      "quote": "Kansetsu-waza is ONLY allowed on the elbow",
      "supports": "Restricción de que el kansetsu-waza solo está permitido en el codo"
    }
  ],
