    },
    {
      "passage_id": "SOR-2026-08-P198-S208",
      "quote": "The athlete is allowed to receive medical treatment for bleeding, on two (2) occasions only.",
      "supports": "El tratamiento del sangrado se permite en dos ocasiones solamente"
    },
    {
      "passage_id": "SOR-2026-08-P198-S208",
